-- Onboarding flow position + DB-backed content
-- ---------------------------------------------------------------------------
-- 1. Adds `flow_position` (resume/back history stack) to tbl_user_memory —
--    flow-control state, kept out of memory_json itself (see onboarding
--    design doc §10: semantic mismatch, not indexable, complicates the
--    "clear stale flow state on re-run" case).
-- 2. Creates tbl_onboarding_content: the admin-editable runtime content
--    store for onboarding copy/options/curated lookups (prompts, option
--    lists with id_order, cuisine/intolerance/pairing/diet-macro curated
--    tables). The flow's STRUCTURAL/logic fields (writes_to, branches,
--    skip_if, options_filter wiring, repeat_for, next, resolution_order)
--    are NOT here — they stay in content/onboarding/flow-structure.yaml,
--    versioned and deployed like code, since a bad live edit there breaks
--    the compile step or misroutes the flow rather than just changing copy.
-- 3. Seeds tbl_onboarding_content from that split — generated by
--    scripts/onboarding-seed/generate-seed-sql.mjs from the YAML files
--    under content/onboarding/, not hand-transcribed. Re-run that script
--    and re-apply this migration (safe: every insert is
--    `on conflict (section_id) do update`) whenever the seed content
--    changes.
--
-- Safe to run more than once, matching this repo's existing migration
-- style (20260910_auth_signup_bootstrap.sql): idempotent DDL, guarded RLS
-- policy creation, upsert seed data.
-- ---------------------------------------------------------------------------

-- 1. Flow position ------------------------------------------------------------
alter table if exists public.tbl_user_memory
  add column if not exists flow_position jsonb not null default '[]'::jsonb;
-- No new RLS policy needed — existing tbl_user_memory_{select,update,insert}_own
-- policies from 20260910_auth_signup_bootstrap.sql already cover this column,
-- same table/row, same account_key = auth.uid() scoping.

-- 2. Content table --------------------------------------------------------------
create table if not exists public.tbl_onboarding_content (
  section_id   text primary key,      -- 'node:<node_id>' | 'curated:<domain>.<table>' | 'content:days_of_week'
  data         jsonb not null,
  updated_at   timestamptz not null default now(),
  updated_by   uuid references auth.users(id)
);

alter table public.tbl_onboarding_content enable row level security;

-- Any authenticated user needs read access to render onboarding. Writes are
-- reserved for admins — no admin-role concept exists yet in this repo, so
-- for this pass writes go through Supabase Studio/SQL (not a policy).
-- Revisit once the admin UI + a real role check exist.
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'tbl_onboarding_content'
      and policyname = 'tbl_onboarding_content_select_authenticated'
  ) then
    execute 'create policy tbl_onboarding_content_select_authenticated on public.tbl_onboarding_content
             for select to authenticated using (true)';
  end if;
end;
$$;

-- 3. Seed content ---------------------------------------------------------------
-- Generated by scripts/onboarding-seed/generate-seed-sql.mjs from
-- content/onboarding/{node_copy,cuisine_curated_data,intolerance_curated_data,
-- pairing_curated_data,diet_macro_curated_data,allergy_macro_curated_data,
-- intolerance_macro_curated_data}.yaml — 32 sections (23 node rows, 8
-- curated-lookup tables, 1 shared days-of-week list). Verified counts:
-- cuisine.sub_cuisines 7 broad cuisines / cuisine.dishes 24 sub-cuisines /
-- intolerance.common 7 / intolerance.by_allergen 6 allergens / pairing.sides
-- 19 dishes / diet_macro.exclusions 8 diets / allergy_macro.exclusions 8
-- allergies / intolerance_macro.exclusions 21 values — matching the source
-- docs' own stated figures (diet_macro/allergies/intolerances counts per
-- this session's product decisions, not the original docs).

